        right_max[n-1] = height[n-1];
        for (int i = n-2; i >= 0; i--) {
            right_max[i] = Math.max(right_max[i+1], height[i]);
        }

        // 計算總接水量
        int water = 0;
        for (int i = 0; i < n; i++) {
            water += Math.min(left_max[i], right_max[i]) - height[i];
        }

